def dead_stock(lines: Iterable[str], case_sizes: Mapping[str, int], today: int, idle_days: int) -> List[str]:
    """List SKUs with positive on-hand whose last ship (or earliest move if never shipped) is >= idle_days old."""
    if idle_days < 1:
