        rec = parse_movement_line(line, case_sizes)
        if rec["day"] > today: continue
        sku, day, mtype = rec["sku"], rec["day"], rec["type"]
        if sku not in earliest_move or day < earliest_move[sku]:
            earliest_move[sku] = day
        if mtype == "SHP" and (sku not in last_ship or day > last_ship[sku]):
            last_ship[sku] = day
    oh = on_hand_by_location(lines, case_sizes, as_of_day=today)
