    for (sku, loc), q in oh.items():
        sku_oh[sku] = sku_oh.get(sku, 0) + q
    dead = []
    for sku, q in sku_oh.items():
        if q <= 0: continue
        ref = last_ship.get(sku, earliest_move.get(sku))
        if ref is not None and today - ref >= idle_days:
            dead.append(sku)
    return sorted(dead)
