from stockflow.first_fit_decreasing import first_fit_decreasing

def split_shipment(lines: Sequence[Tuple[str, int, int]], max_parcel_grams: int) -> List[Dict[str, int]]:
    if max_parcel_grams <= 0:
        raise ValueError("max_parcel_grams must be > 0")

    merged: Dict[str, Tuple[int, int]] = {}
    for sku, qty, w in lines:
        if qty <= 0 or w <= 0: raise ValueError("qty/weight must be > 0")
        if sku in merged and merged[sku][1] != w: raise ValueError("inconsistent weight")
        merged[sku] = (merged.get(sku, (0, w))[0] + qty, w)

    blocks: List[Tuple[str, int, int]] = []
    for sku, (qty, w) in merged.items():
        if w > max_parcel_grams: raise ValueError("item too heavy")

        items_per_parcel = max_parcel_grams // w
        full_blocks = qty // items_per_parcel
        remainder = qty % items_per_parcel

        for _ in range(full_blocks):
            blocks.append((sku, items_per_parcel, items_per_parcel * w))
        if remainder > 0:
            blocks.append((sku, remainder, remainder * w))

    # first_fit_decreasing expects a list of (id, weight)
    # We'll use a unique ID for each block to keep them together
    ffd_input = [(f"{sku}_{i}", weight) for i, (sku, qty, weight) in enumerate(blocks)]
    # We need to map these IDs back to the actual SKU and quantity
    id_to_data = {f"{sku}_{i}": (sku, qty) for i, (sku, qty, weight) in enumerate(blocks)}

    bins = first_fit_decreasing(ffd_input, max_parcel_grams)

    res: List[Dict[str, int]] = []
    for b in bins:
        parcel = {}
        for block_id, _ in b:
            sku, qty = id_to_data[block_id]
            parcel[sku] = parcel.get(sku, 0) + qty
        res.append(parcel)
    return res"
